# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
J=[['拉丁 iocus／jocus','玩笑、游戏、消遣']]
JK=J+[['英语 joke，早期也写 joque','笑话、玩笑；也作动词表示开玩笑']]
JL=J+[['拉丁 ioculus → ioculari／ioculator','小玩笑 → 逗乐、表演／逗乐者'],['古法语 jogleor／盎格鲁法语 jogelour 等与早期英语形式汇合','娱乐表演者、变戏法的人'],['英语 juggler；juggle 也受法语 jogler 及逆构影响','杂耍者；表演杂耍']]
JP=J+[['古法语 jeu“游戏” + parti“分开的” → jeu parti','胜负未分的局面；结果不确定'],['盎格鲁法语及中古英语 → jeopardy','不确定的局面 → 危险、风险']]
WA=[
E('joke','英 /dʒəʊk/；美 /dʒoʊk/','笑话；玩笑；开玩笑','把一句话或一个情境转个弯，让人觉得好笑。','来自拉丁 iocus“玩笑、游戏”；动词可由名词形成，也有直接联系拉丁 iocari 的分析。',JK,'tell a joke 是讲一个笑话；make a joke about something 是拿某件事开玩笑。说 something is a joke，也可能是在批评它荒唐、完全不值得认真对待。玩笑是说话者的意图，不保证听的人也觉得好笑。','tell a joke；make a joke；joke about something；You must be joking.','joke 范围很广；prank 更常是实际做出的恶作剧；pun 是利用词义或读音双关的笑话。',('He told a joke to ease the tension.','他讲了个笑话来缓和紧张气氛。'),('I was joking about the price; I know it is expensive.','我刚才拿价格开玩笑；我知道它很贵。'),('The so-called apology was a joke.','那份所谓的道歉简直像儿戏。'),sources=['https://www.etymonline.com/word/joke','https://en.wiktionary.org/wiki/joke']),
E('joking','英 /ˈdʒəʊkɪŋ/；美 /ˈdʒoʊkɪŋ/','开玩笑；开玩笑的；闹着玩的','这句话不是按字面认真宣布，而是在用玩笑语气说。','joke 去掉末尾 e，加 -ing；可以是动词形式，也可以描述语气或开玩笑这件事。',JK+[['英语 joke → joking','开玩笑这一动作；玩笑式的']],'I’m joking 表示自己在说笑。a joking tone 描述轻松逗趣的口气；joking aside 则把玩笑放到一边，开始认真谈。判断是不是玩笑仍要结合语气和场合，不能只靠这一个标签替冒犯开脱。','a joking tone；only joking；joking aside；Are you joking?','joking 强调在说笑；funny 强调有趣或好笑，也可能表示古怪。开玩笑的话不一定 funny。',('She said it in a joking tone.','她用开玩笑的口气说了那句话。'),('Joking aside, we need to make a decision today.','说正经的，我们今天需要作出决定。'),sources=['https://www.etymonline.com/word/joking','https://en.wiktionary.org/wiki/joking']),
E('jokingly','英 /ˈdʒəʊkɪŋli/；美 /ˈdʒoʊkɪŋli/','开玩笑地；打趣地','告诉读者这话带着说笑的意思，不是严肃表态。','joking + -ly，表示说话或行动的方式。',JK+[['英语 joking → jokingly','开玩笑的 → 以玩笑方式']],'jokingly 常修饰 said、asked、called 等动词，交代原话的语气。它不能代替上下文：有人是亲切打趣，也有人借玩笑表达真实不满。阅读时把它看成语气提示，而不是“内容完全不重要”。','say jokingly；ask jokingly；jokingly call someone…。','jokingly 往往是说笑；sarcastically 常有讽刺、挖苦意味。两者有时重叠，但不是固定同义词。',('He jokingly called himself the office coffee expert.','他打趣地称自己是办公室的咖啡专家。'),('“Are you paying for everyone?” she asked jokingly.','“你要请所有人吗？”她开玩笑地问。'),sources=['https://www.etymonline.com/word/joking','https://en.wiktionary.org/wiki/jokingly']),
E('joker','英 /ˈdʒəʊkə/；美 /ˈdʒoʊkər/','爱开玩笑的人；扑克牌中的王牌；家伙〔口语〕','平时说笑的人叫 joker；牌里的特殊一张也用了这个名字。','joke + -er“做这件事的人”；扑克牌专义的命名还可能受到德语牌戏名 Jucker 的影响。',JK+[['英语 joke + -er → joker','说笑的人'],['后来 joker 的口语及扑克牌用法','家伙；牌中的特殊王牌，牌名历史可能有其他影响']],'He’s a joker 常说他爱逗人笑。a joker in a deck 指扑克牌里的王牌，具体怎样使用由游戏规则决定。说 some joker did this 往往带不满，类似“哪个家伙干的”，不一定在夸他幽默。','a practical joker；the joker in the deck；some joker。','joker 是人或牌；joke 是玩笑本身。牌义不要仅凭小丑图案编成唯一的历史来源。',('My uncle is a joker who can make everyone laugh.','我叔叔很爱说笑，能把大家都逗乐。'),('This game does not use the jokers.','这个游戏不使用王牌。'),sources=['https://www.etymonline.com/word/joker','https://en.wiktionary.org/wiki/joker']),
E('jokester','英 /ˈdʒəʊkstə/；美 /ˈdʒoʊkstər/','爱逗趣的人；爱说笑的人','在人群里经常接一句俏皮话，把气氛带活的人。','joke + -ster，后缀在这里表示以某种行为见长的人。',JK+[['英语 joke + -ster → jokester','经常开玩笑的人']],'jokester 是偏口语的称呼，常见于美式英语。可以亲切地说某人是家里的开心果，也可能在严肃场合提醒他别老开玩笑。它描述习惯，不一定表示对方以喜剧表演为职业。','a family jokester；a natural jokester；the office jokester。','comedian 通常指喜剧表演者或演员；jokester 可以只是日常生活里特别爱说笑的人。',('She has always been the jokester in our family.','她一直是我们家最爱逗趣的人。'),('Even the office jokester stayed serious during the announcement.','宣布消息时，连办公室里最爱说笑的人都很严肃。'),sources=['https://en.wiktionary.org/wiki/jokester','https://www.merriam-webster.com/dictionary/jokester']),
E('jocular','英 /ˈdʒɒkjʊlə/；美 /ˈdʒɑːkjələr/','爱开玩笑的；诙谐的；带玩笑口吻的〔较正式〕','话题并不一定轻松，但说话人故意带上一点打趣的口吻。','拉丁 iocus → 指小形式 ioculus → iocularis，经借词成为 jocular；不能拆成 joc + ocular“眼睛的”。',J+[['拉丁 ioculus → iocularis','小玩笑 → 诙谐的'],['英语 jocular','爱开玩笑的；玩笑式的']],'a jocular remark 是诙谐打趣的话，a jocular manner 是爱说笑的态度。这个词较适合书面描写人物语气，有时暗示对方用玩笑避开了严肃问题，但并非每次都含贬义。','a jocular tone；a jocular remark；a jocular manner。','jocular 强调语气在说笑；joyful 强调内心或气氛喜悦。一个人可以用 jocular 的口吻掩盖紧张。',('He replied in a jocular tone.','他用打趣的口吻回答。'),('Her jocular manner helped the new colleagues relax.','她诙谐的态度让新同事们放松了下来。'),sources=['https://www.etymonline.com/word/jocular','https://en.wiktionary.org/wiki/jocular']),
E('juggle','/ˈdʒʌɡəl/','抛接杂耍；同时兼顾；巧妙调配；做手脚','像同时抛着几个球，一件事刚接住，另一件又得马上处理。','与拉丁 ioculari“说笑、逗乐”的法语后代相连；英语也部分由较早的 juggler 逆构。',JL+[['英语 juggle 的具体与比喻用法','手上抛接物件 → 同时处理多件事；也可指操弄']],'juggle three balls 是实际抛接三个球；juggle work and family 是在工作、家庭之间来回安排，尽量不让任何一边“掉下来”。juggle the figures 有时是调整数字，有时暗示做手脚，要看语境。','juggle work and family；juggle several tasks；juggle the figures。','multitask 说同时处理多项任务；juggle 常更突出时间有限、来回协调的吃力感。',('She juggles a full-time job and evening classes.','她要兼顾全职工作和晚间课程。'),('He can juggle three balls without dropping one.','他能抛接三个球，一个也不掉。'),sources=['https://www.etymonline.com/word/juggle','https://en.wiktionary.org/wiki/juggle']),
E('juggler','英 /ˈdʒʌɡlə/；美 /ˈdʒʌɡlər/','杂耍者；抛接杂耍演员','靠手上的灵巧，让几个物件在空中有条不紊地来回。','现代可看 juggle + -er；历史上 juggler 的英语前身更早，不能只讲成现代 juggle 派生。',JL,'juggler 今天常指表演抛接球、棒等物件的人。早期同族词的范围更宽，包括逗乐、变戏法等表演者；现代意义逐渐集中到这种手上功夫。比喻用法也能形容善于同时调度许多事情的人。','a street juggler；a professional juggler；watch a juggler。','magician 通常靠魔术效果表演；juggler 常展示可见的抛接技巧。两类技艺可以由同一演员兼做。',('A street juggler entertained the crowd.','一名街头杂耍演员逗乐了人群。'),('The juggler kept all five clubs moving through the air.','杂耍演员让五根棒始终在空中轮流抛接。'),sources=['https://www.etymonline.com/word/juggler','https://en.wiktionary.org/wiki/juggler']),
E('juggling','/ˈdʒʌɡlɪŋ/，也可读 /ˈdʒʌɡəlɪŋ/','抛接杂耍；同时安排多件事','让几件事不断交换位置，勉强都能接得住。','juggle + -ing；既可以是动词形式，也可以是活动名词。',JL+[['英语 juggle → juggling','杂耍活动；来回兼顾和调整']],'juggling 是一项技巧，也能概括协调复杂日程的工作。a lot of juggling 往往表示不得不挪时间、换安排，才把几件事放进去。这里的球换成了任务，画面还在。','learn juggling；some juggling of schedules；a juggling act。','juggling 说协调过程；balance 更突出协调后的平衡状态。实际生活中也常一起使用。',('Learning juggling takes patience and practice.','学习抛接杂耍需要耐心和练习。'),('It took some juggling to fit both meetings into the afternoon.','我们调整了一番，才把两场会议都安排进下午。'),sources=['https://en.wiktionary.org/wiki/juggling','https://www.etymonline.com/word/juggle']),
E('jeopardy','英 /ˈdʒepədi/；美 /ˈdʒepərdi/','危险；受威胁的处境','原来像一场胜负未定的游戏，后来强调可能输掉重要东西的风险。','经古法语 jeu parti；jeu“游戏”接拉丁 iocus，parti 有“分开、分配”的意思。',JP,'in jeopardy 最常说某件重要的东西处在危险中：工作可能丢，计划可能失败，安全可能受损。它不表示损失已经发生，而是局面让损失成为现实风险。现在语气通常比一般“不确定”更严重。','put something in jeopardy；be in jeopardy；place jobs in jeopardy。','in jeopardy 强调受损或失去的风险；uncertain 只说结果未定，不一定带危险。',('The delay put the entire project in jeopardy.','这次延误使整个项目面临失败风险。'),('Hundreds of jobs are in jeopardy.','数百个工作岗位面临不保的风险。'),sources=['https://www.etymonline.com/word/jeopardy','https://en.wiktionary.org/wiki/jeopardy']),
E('jeopardize','英 /ˈdʒepədaɪz/；美 /ˈdʒepərdaɪz/','危及；使面临受损或失败的风险','原本还能守住的东西，被某个行为推到了危险边缘。','jeopardy + -ize“使进入某状态”；英式也常写 jeopardise。',JP+[['英语 jeopardy + -ize → jeopardize','危险处境 → 使处于危险']],'jeopardize your career 是让职业前途面临风险，jeopardize the agreement 是可能使协议破裂。这个动词强调造成风险，不必已经导致最终失败；所以常用来说明一个决定可能付出的代价。','jeopardize safety；jeopardize a project；jeopardize someone’s chances。','destroy 表示破坏已经达到很强程度；jeopardize 可以还在风险阶段。不要把它一律译成“彻底毁掉”。',('Ignoring the warning could jeopardize everyone’s safety.','无视这条警告可能危及所有人的安全。'),('She did not want to jeopardize her chances of promotion.','她不想让自己的晋升机会受到影响。'),sources=['https://www.etymonline.com/word/jeopardize','https://en.wiktionary.org/wiki/jeopardize']),
]
